INSERT INTO REPT_PRVNT_MNG
     ( PET_SN
     , CKUP_RCD_SN
     , REPT_PRVNT_ARTCL_CD
     , REPT_CYCLE_CD
     , BGNG_YMD
     , CYCLE_DRCT_INPT_DAY_CNT
     , DEL_YN
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{petSn}
     , #{ckupRcdSn}
     , #{reptPrvntArtclCd}
     , #{reptCycleCd}
     , #{bgngYmd}
     , #{cycleDrctInptDayCnt}
     , 'N'
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

