   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE REPT_PRVNT_MNG_SN = #{reptPrvntMngSn}
   AND DEL_YN = 'N'

